import{a as n}from"./chunk-RBZKN5VR.js";import{a as t}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var r=t(n,["문제마다 순서대로 드래그해 상자를 그리세요. 상자는 겹쳐도 돼요. 상자의 번호를 드래그하면 옮겨져요. 상자를 클릭하면 모서리로 크기를 바꾸거나 표시가 들어갈 곳을 정할 수 있어요. 그다음 문제마다 배점, 채점 방식(정답/오답, 또는 단답형은 0~2 같은 척도), 정답이 있으면 정답을 넣으세요. 정답은 돌려주는 답안지에 금색 메모로 넣을 수 있어요.","정답 메모","모든 문제","감점된 곳","끄기","모든 답안지에서, 정답이 있는 문제마다 옆에 정답을 적은 금색 메모가 들어가요.","학생이 감점된 문제마다 옆에 정답을 적은 금색 메모가 들어가요.","입력한 정답은 채점하는 동안 나만 봐요.","{q}번 문제의 정답 메모로 가는 선이 시작되는 곳이에요. 드래그하면 옮겨져요.","정답 선 시작 위치","표시 옆","각 상자 오른쪽","금색 핀을 드래그하지 않았다면.","각 상자 아래","표시 옆","상자 오른쪽","상자 아래","답안지별로 옮긴 정답 메모는 저장하면 제자리로 돌아가요.","취소","페이지를 클릭하세요…","평가 기준","{q}번 문제의 평가 기준","이 상자 빼기","목표","{q}번 문제의 학습 목표","목표 없음","목표 편집…","문항에 학습 목표 달기…","채점 방식","✓와 ✗","점수","오답에 ✗","그대로 두기","답","정답","선택 사항","고른 상자 단축키: 화살표로 이동, Shift + 화살표로 크기 조절, Ctrl D로 바로 아래에 복사, Del 키로 빼기.","채점됨","정답 선:","{at}에서 시작해요. 금색 핀을 드래그하면 바뀌어요.","{at}(으)로 되돌리기","드래그한 금색 핀에서 시작해요","평가 기준 {list}의 수준을 마저 채우거나 지우세요","평가 기준 {k}의 수준 {n} 최저 점수","지우기","고르게 나누기","{n}칸을 모두 채우세요. 각 칸은 앞 칸 이상의 점수여야 해요.","점수를 수준으로","아직 수준이 없어요. 이 평가 기준은 점수만 보여요.","{n}점 만점","수준 {n}에는 {p}점이 필요한데, 이 문제들의 합은 {max}점이에요.","각 수준을 받는 최저 점수","여백에","여백으로 되돌리기","{q}번 문제 표시:","새 상자 채점 방식","합계 없음","아직 상자가 없어요","그릴 곳","{n}페이지","표시가 들어갈 곳이에요. 드래그하면 옮겨져요.","점수","답안지별로 옮긴 정답 메모 되돌리기 ({n})","질문","문제 이름","정답 / 오답","상자 저장","상자를 저장했어요","상자를 저장했어요. 이제 점수는 {n}점 만점이에요.","상자를 저장했어요. 이제 빠른 채점이 이 과제를 {n}점 만점으로 채점해요. 루브릭 점수는 저장된 채로 남지만 더 이상 반영되지 않아요.","표시 위치","각 상자 왼쪽","오른쪽","위치를 따로 고르지 않았다면","표시 위치 고르기","{n}페이지에서 {q}번 문제가 있는 곳을 고르세요","{n}문제, {pts}점 만점","{n}문제, {pts}점 만점","퀴즈 상자","합계","모든 문제를 채점하면 점수가 {n}페이지에 들어가요.","모든 문제를 채점하면 수준이 {n}페이지에 들어가요.","선택 사항: 답안지에 수준을 넣을 위치(예: A 6).","옮기기","선택 사항: 답안지에 점수를 넣을 위치(예: 18/20 = 90%).","위치 고르기","{n}점 중 {s}점의 뜻","각 점수의 뜻","0~{n}","채점하는 동안 버튼에 보여요","추가","+ 보기","빈 사본","브라우저가 인쇄 창을 막았어요","문제와 동그라미","취소","보기 {l}","보기 {l} 빼기","빼기","거짓","정답","정답: {k}","정답: {list}. 모두 고르고 다른 것은 고르지 않아야 점수를 받아요.","문제 유형","이것을 정답으로","객관식","해당하는 것 모두 고르기","학생 이름","글자를 클릭해 정답을 정하세요.",{one:"학생 {n}명분 인쇄…",other:"학생 {n}명분 인쇄…"},"인쇄할 내용","점수","단답형","학생은 줄 위에 써요. 교사 칸에서 0~{n} 점수 동그라미를 칠해 채점하면, 스캔이 그 점수도 읽어요. 비워 두고 빠른 채점에서 채점해도 돼요.","저장","퀴즈를 저장했어요","퀴즈를 저장했어요. 이번 변경으로 동그라미 위치가 바뀌니 다시 인쇄하세요. 전에 인쇄한 사본은 스캔이 읽을 수 없어요.","답안지만","정답 보기","퀴즈 만듦","{n}문제, {pts}점 \xB7 한 부에 {pages}페이지 \xB7 스캔 채점 {auto}개, 직접 채점 {sa}개","{n}번 문제","문제를 입력하세요","문제를 입력하세요(답안지에서는 선택 사항)","참/거짓","퀴즈 만들기","퀴즈 편집","참","위로 이동","내 도우미","전체","여기는 모두 채점했어요. 채점한 것을 보려면 전체를 고르세요.","학생 답안지에 금색으로 들어가요. 답이 들어갈 곳은 상자에서 바꿀 수 있어요.","답","여백 의견","페이지 위 글","상자","문제별","학생별","지우기","빠른 채점 닫기","의견","이 답안지에 의견이나 글 쓰기 (C)","이 답만 들어가고, 위에 문제와 정답이 붙어요. 학생 이름, 점수, 내 표시, 파일 이름은 빠지고, 이름 가림은 칠해져요. 하지만 학생의 글씨와 말은 그대로 보여요.","어디에도 보내지 않아요. 직접 어딘가에 붙여 넣기 전까지 그림은 이 컴퓨터에만 있어요.","그림에 보이는 것.","알겠어요","색","{q} 그림을 복사했어요. {ai}에 붙여 넣고 물어보세요.","⧉ 복사","이 답을 그림으로 복사해서 도우미나 어디에든 붙여 넣을 수 있어요. 이름, 점수, 표시는 들어가지 않아요 (P)","{of}개 중 {n}개 채점함","페이지를 그리는 중…","예시","우수 예시로 보관됨. 클릭하면 뺍니다 (E)","이 답안을 이름을 가려 우수 예시로 보관 (E)","전체 너비","0.5점 더하기 또는 빼기 (H)","키: 숫자는 그 점수, H는 \xBD 더하기,","C 의견, P 그림 복사, 화살표로 이동, 스페이스 바 전체 페이지, Ctrl Z 실행 취소, [ ]로 문제 이동. 표시를 드래그하면 그 답안지에서만 옮겨져요.","답을 클릭하면 ✗가 표시되고, 다시 클릭하면 빠져요. 키: 1 정답, 0이나 X 오답,","답을 클릭하면 ✗가 표시되고, 다시 클릭하면 빠져요. 키: ↑ ↓로 이동, 숫자는 그 점수, C 의견, P 그림 복사, 스페이스 바 전체 페이지, Ctrl Z 실행 취소, [ ]로 학생 이동.","드래그: 이 답안지 위치 맞추기","클릭: 오답 / 정답. 드래그: 이 답안지 위치 맞추기","색","득점에 따라","만점: 2/2 \xB7 부분 점수: 1/2 \xB7 0점: 0/2. 합계와 점수 도장은 ✗ 색 그대로예요.","만점은 ✓ 색, 부분 점수는 호박색, 0점은 ✗ 색","이미 준 표시도 같이 바뀌어요.","✓ 정답","점수","✗와 같게","점수를 ✗ 색으로","표시 색","✗ 오답","정답이에요.","모든 답안지에 금색 메모로 들어가요.","이 문제에서 감점된 답안지에 금색 메모로 들어가요.","정답 메모가 꺼져 있어요. 상자에서 켜세요.","드래그하면 이 답안지에서만 이 표시를 옮겨요","이 페이지는 학생의 스캔에 없어요.","채점할 스캔 답안지가 없어요","채점 안 됨","들어갈 곳","의견:","{c} 의견","Enter로 저장, Esc로 취소","학생 답안지에 쓸 내용을 입력하세요…","글:","클릭해서 바꾸기","{n} / {of}","학생 답안지 열기","⤢ 전체 페이지","{q}번 문제, {n}페이지","뒤로 (Esc)","학생의 전체 페이지 보기 (스페이스 바)","이 답안지에서 표시가 들어갈 곳이에요. 드래그하면 이 답안지에서만 옮겨져요.","{n}점","{n}점","다음 문제","질문","이전 문제","{q}번 문제","위치 초기화","이 표시를 문제의 표시 위치로 되돌리기","나머지는 정답 처리","나머지에 {n} 주기","정답 ({n})","{n}점, 정답 또는 오답","{n}점, 정답 또는 오답","다음 학생","학생","이전 학생","저장","이 브라우저는 그림을 복사할 수 없어서 {q}을(를) 그림 파일로 저장했어요.","0~{n}점 척도","보여 줄 답","크기","빠른 채점","답 보기","오답 (0)","다시 읽기","모든 페이지를 다시 읽어요. 이미 있는 답은 그대로 남아요.","모든 점수는 빠른 채점에서 바꿀 수 있어요. Ctrl Z를 누르면 스캔이 준 점수를 되돌려요.","다음","답안지에서 이 퀴즈의 페이지를 찾지 못했어요","없음","바뀐 것이 없어요","확인할 것이 없어요.","{n}페이지는 퀴즈를 마지막으로 바꾸기 전에 인쇄돼서 읽지 않았어요. 빠른 채점에서 채점하세요.","1페이지는 퀴즈를 마지막으로 바꾸기 전에 인쇄돼서 읽지 않았어요. 빠른 채점에서 채점하세요.","이것들은 분명하지 않아서 자동으로 채점할 수 없었어요. 학생마다 의도한 답을 고르세요. 강조된 버튼이 스캔의 추측이에요.","{q}번 문제 \xB7 {why}","동그라미를 읽는 중…","점수 저장","점수 {n}개를 저장했어요","점수 1개를 저장했어요","학생 {who}명의 퀴즈에서 답 {n}개를 채점했어요","학생 {who}명의 퀴즈에서 답 {n}개를 채점했어요","확인 필요","읽은 페이지","읽은 답","읽은 답, 빈칸 {n}개","페이지의 코드로 찾은 학생","학생의 답","학생의 답","퀴즈 스캔 결과","너무 흐림","다른 동그라미에도 표시됨","점수 불분명","동그라미 두 개 칠함","불분명","내 점수"],null);export{r as default};
